-- The workspace of one build of a game's native module (Docs/Decisions/0030-m19-contract.md decision 30), generated by
-- Scripts/BuildNative.py, never by hand:
--
--   premake5 --file=Scripts/Premake/NativeModule.lua --native-inputs=<out>/Workspace/Inputs.json --fatal vs2026
--
-- Inputs.json (Scripts/Lib/native_build.py write_workspace_inputs) names the build: its Kind ("Module" or "Runtime"),
-- Configuration, the game's ProjectRoot and its Sources (absolute; ListNativeSources' files, after the lint), the
-- WorkspaceDirectory, OutputDirectory and IntermediateDirectory below the build's output directory, and for a Runtime
-- the LibraryDirectories of the libraries it links. The module's code is compiled exactly like engine code: the
-- engine's own ApplyWorkspaceSettings(), ApplyFirstPartySettings() and UseRuntimeDependencies() (Dependencies.lua), so
-- precise floating point, warnings as errors, the first-party defines and the instruction set of the code it runs
-- beside, in every kind:
--   Module   NativeModule.dll, the editor's shared library of the editor's configuration (Debug or Release): the
--            sources with ENGINE_NATIVE_SHARED_LIBRARY, which makes ENGINE_NATIVE_MODULE export the module's two entry
--            functions, and no library linked (NativeApi.h is header-only), so the library holds no second copy of the
--            engine's process-level state.
--   Runtime  Runtime.exe, the game's Runtime of the export's configuration: the prebuilt Runtime's executable
--            (ApplyRuntimeExecutableSettings) with the sources instead of NoNativeModule.cpp, so the module's
--            ENGINE_NATIVE_MODULE defines GetLinkedNativeModule, linked with the configuration's RuntimeCore and Engine
--            libraries (bin/<OutputDir>/) and the vendored libraries the prebuilt Runtime links.

newoption
{
	trigger = "native-inputs",
	value = "path",
	description = "The build's Inputs.json, which Scripts/BuildNative.py writes"
}

include "../../Dependencies.lua"

local function Fail(message)
	error("Scripts/Premake/NativeModule.lua: " .. message, 0)
end

local function ReadInputs()
	local file = _OPTIONS["native-inputs"]
	if file == nil then
		Fail("--native-inputs=<Inputs.json> is required (Scripts/BuildNative.py generates this workspace)")
	end
	local text = io.readfile(file)
	if text == nil then
		Fail("cannot read " .. file)
	end
	local inputs, problem = json.decode(text)
	if inputs == nil then
		Fail(file .. " is not valid JSON: " .. tostring(problem))
	end
	for _, key in ipairs({ "Kind", "Configuration", "ProjectRoot", "WorkspaceDirectory", "OutputDirectory", "IntermediateDirectory" }) do
		if type(inputs[key]) ~= "string" or inputs[key] == "" then
			Fail(file .. ": " .. key .. " must be a non-empty string")
		end
	end
	if inputs.Kind ~= "Module" and inputs.Kind ~= "Runtime" then
		Fail(file .. ": Kind must be Module or Runtime, not " .. inputs.Kind)
	end
	if type(inputs.Sources) ~= "table" or #inputs.Sources == 0 then
		Fail(file .. ": Sources must list the module's sources")
	end
	if type(inputs.LibraryDirectories) ~= "table" then
		Fail(file .. ": LibraryDirectories must be a list")
	end
	return inputs
end

-- The display name ApplyFirstPartySettings() defines as ENGINE_PRODUCT_NAME in executables: premake5.lua's workspace name,
-- read from the one line that defines it (as Scripts/Lib/paths.py reads it), so the Runtime compiles as the prebuilt one.
local function ReadWorkspaceName()
	local text = io.readfile(RepositoryRoot .. "/premake5.lua")
	local name = text and text:match("\nWorkspaceName = \"([^\"]+)\"")
	if name == nil then
		Fail("cannot read the workspace name from " .. RepositoryRoot .. "/premake5.lua")
	end
	return name
end

local Inputs = ReadInputs()
WorkspaceName = ReadWorkspaceName()

-- The module's sources and their include root, the game's project directory, so a source includes its module's own
-- headers by their project-relative path ("Native/Spinner.h"), and the build's directories.
local function AddModuleSources(objects)
	files (Inputs.Sources)
	includedirs { Inputs.ProjectRoot }
	targetdir (Inputs.OutputDirectory)
	objdir (Inputs.IntermediateDirectory .. "/" .. objects)
end

workspace "NativeModule"
	configurations { Inputs.Configuration }
	location (Inputs.WorkspaceDirectory)
	ApplyWorkspaceSettings()

if Inputs.Kind == "Module" then
	project "NativeModule"
		kind "SharedLib"
		ApplyFirstPartySettings()
		UseRuntimeDependencies()
		-- The compile settings of the code the module runs beside, but no library: everything the module reaches in the
		-- engine goes through NativeApi.h's interfaces.
		removelinks { "*" }
		defines { "ENGINE_NATIVE_SHARED_LIBRARY" }
		AddModuleSources("NativeModule")
else
	project "Runtime"
		kind "ConsoleApp"
		ApplyFirstPartySettings()
		ApplyRuntimeExecutableSettings(Inputs.WorkspaceDirectory)
		libdirs (Inputs.LibraryDirectories)
		AddModuleSources("Runtime")
end
